require "action_dispatch/middleware/session/abstract_store"

module ActionDispatch
  module Session
    # Stores the Rails session hash in the browser_sessions table.
    #
    # Follows Rails' server-side session pattern (as generated by
    # `rails g authentication`): the browser holds only a signed reference, the
    # row is found by a SHA-256 of the session id (so a database leak cannot be
    # replayed as a cookie), the session is resolved once per request and
    # logging out or `reset_session` deletes the row.
    #
    # Replaces the former Redis-backed CacheStore without changing its
    # semantics: expiry is `expire_after` from the last write (not refreshed by
    # requests that don't load the session), expired rows are ignored on read
    # whether or not cleanup has removed them, and a session deleted by another
    # request (e.g. logout) is not restored by a request still using it.
    #
    # TRANSITION (see SessionStorage and docs/documents/session-storage-cutover.md):
    # sessions are never copied between stores on read. Writes and deletes
    # update the database and, until the `database` phase, Redis together under
    # one advisory lock per session.
    #
    # Cookies are signed only once old code can no longer be running (the
    # `database` phase), or when the browser already sent a signed one. An
    # unsigned cookie is accepted only for rows still marked unsigned, and the
    # response replaces it with a signed one; the `signed_cookie` column and the
    # unsigned branches can be removed once `expire_after` has passed after the
    # `database` phase is fully rolled out.
    class DatabaseStore < AbstractSecureStore
      LOADED_ID = "action_dispatch.session.database_store.loaded_id".freeze
      SIGNED_COOKIE = "action_dispatch.session.database_store.signed_cookie".freeze

      def find_session(req, sid)
        found = sid && (SessionStorage.redis_authoritative? ? find_in_redis(sid) : find_in_database(req, sid))

        if found
          req.set_header(LOADED_ID, sid.private_id)
          [sid, found]
        else
          [generate_sid, {}]
        end
      end

      def write_session(req, sid, session, options)
        return delete_everywhere(sid) && sid if session.blank?

        written = BrowserSession.with_advisory_lock(sid.private_id) do
          if SessionStorage.redis_authoritative?
            write_redis_authoritative(req, sid, session, options)
          else
            write_database_authoritative(req, sid, session, options)
          end
        end

        written && sid
      end

      def delete_session(_req, sid, options)
        delete_everywhere(sid)
        generate_sid unless options[:drop]
      end

      def extract_session_id(req)
        signed = req.cookie_jar.signed[key]
        req.set_header(SIGNED_COOKIE, signed.present?)
        value = signed || req.cookies[key]
        value && Rack::Session::SessionId.new(value)
      end

    private

      def set_cookie(request, _response, cookie)
        jar = sign_cookie?(request) ? request.cookie_jar.signed : request.cookie_jar
        jar[key] = cookie
      end

      def sign_cookie?(req)
        SessionStorage.database? || req.get_header(SIGNED_COOKIE) == true
      end

      def find_in_database(req, sid)
        row = BrowserSession.live.find_by(session_id: sid.private_id)
        return unless row
        # An unsigned cookie is only honoured for a row from before signing
        return if row.signed_cookie? && req.get_header(SIGNED_COOKIE) == false

        row.payload
      end

      def write_database_authoritative(req, sid, session, options)
        if req.get_header(LOADED_ID) == sid.private_id
          # Updating rather than inserting means a row deleted by another
          # request is not restored by this one.
          return false unless update_row(req, sid, session, options)
        else
          upsert_row(req, sid, session, options)
        end

        mirror_to_redis!(sid, session, options) if SessionStorage.redis_written?
        true
      end

      def write_redis_authoritative(req, sid, session, options)
        return false if req.get_header(LOADED_ID) == sid.private_id && !redis_exist?(sid)

        redis_write(sid, session, options)
        upsert_row(req, sid, session, options)
        true
      end

      def update_row(req, sid, session, options)
        BrowserSession.live.where(session_id: sid.private_id).update_all(
          session_data: BrowserSession.dump(session),
          signed_cookie: sign_cookie?(req),
          expires_at: expiry(options),
          updated_at: Time.current
        ).positive?
      end

      def upsert_row(req, sid, session, options)
        BrowserSession.upsert(
          {
            session_id: sid.private_id,
            session_data: BrowserSession.dump(session),
            signed_cookie: sign_cookie?(req),
            expires_at: expiry(options)
          },
          unique_by: :session_id
        )
      end

      def expiry(options)
        options[:expire_after].seconds.from_now
      end

      def delete_everywhere(sid)
        BrowserSession.with_advisory_lock(sid.private_id) do
          BrowserSession.where(session_id: sid.private_id).delete_all
          if SessionStorage.redis_written?
            Rails.cache.delete(redis_key(sid.private_id))
            Rails.cache.delete(redis_key(sid.public_id))
          end
        end
        true
      end

      def redis_key(id)
        "_session_id:#{id}"
      end

      def find_in_redis(sid)
        Rails.cache.read(redis_key(sid.private_id)) || Rails.cache.read(redis_key(sid.public_id))
      end

      # Rails.cache swallows Redis errors and returns a falsy value. Failing here
      # rolls back the database write, so rolling back to Redis can't lose it.
      def mirror_to_redis!(sid, session, options)
        redis_write(sid, session, options) || raise("Could not mirror session to Redis")
      end

      def redis_write(sid, session, options)
        Rails.cache.write(redis_key(sid.private_id), session, expires_in: options[:expire_after])
      end

      # Bypasses the request-local cache, which still holds the entry this
      # request loaded and so can't see a delete made by another request.
      def redis_exist?(sid)
        exist = -> { Rails.cache.exist?(redis_key(sid.private_id)) || Rails.cache.exist?(redis_key(sid.public_id)) }
        Rails.cache.respond_to?(:with_local_cache) ? Rails.cache.with_local_cache(&exist) : exist.call
      end
    end
  end
end
